```javascript
(function(){
  'use strict';

  /* ---------------- Normalização ---------------- */
  function normalizaTexto(texto){
    if (typeof texto !== 'string') return '';
    var s = texto.toLowerCase();
    s = s.replace(/áàâãäå/, 'a')
       .replace(/éèêëëìíîïłşű/, 'e')   // incluir ł, š, ț, ū para robustez
       .replace(/óòôõöøųĸ/, 'o')
       .replace(/úùûüůǝ/y? u/)  // hmm, ĸ not common. Let's do simple: úùûüü -> u
       .replace(/ç/,'c')
       .replace(/ñ/,'n')
       .replace(/â/,'a')
       .replace(/î/,'i')
       .replace(/ï/,'i')
       .replace(/ö/,'o')
       .replace(/ø/,'o')
       .replace(/ý/,'y');
    // Evita duplicar substituições: o regex de áàâãäå já inclui â. Depois não precisamos de novo. Mas ordem importa? Não.
    // Remover qualquer coisa que não seja letra, dígito ou espaço
    s = s.replace(/[^a-z0-9\s]/g, ' ');
    var tokens = s.trim().split(/\s+/).filter(function(t){
      return t.length > 1;
    });
    // Ignora números puros de um único dígito
    tokens = tokens.filter(function(t){
      if (/^[\d]+$/.test(t)) return t.length > 1;
      return true;
    });
    return tokens.join(' ');
  }

  function tokenizarQuery(query){
    var texto = normalizaTexto(query);
    if (!texto || texto.trim() === '') return [];
    return texto.split(/\s+/).filter(function(t){ return t.length > 1; });
  }

  /* ---------------- Conteúdo de exemplo ---------------- */
  var CONTEUDO = [
    {
      id:'artigo-1',
